/// </summary>
/// <param name = "_fieldTyp">NDXMappingDataFromAX2009FieldTyp</param>
/// <param name = "_fromStringValue">NDXFromStringValue</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXMappingDataTransferFromAX2009</returns>
public static NDXMappingDataTransferFromAX2009StringTyp find(
    NDXMappingDataFromAX2009FieldTyp _fieldTyp, 
    NDXFromStringValue _fromStringValue, 
    boolean _forUpdate = true)
{
    NDXMappingDataTransferFromAX2009StringTyp nDXMappingDataTransferFromAX2009;
    nDXMappingDataTransferFromAX2009.selectForUpdate(_forUpdate);
    select firstonly nDXMappingDataTransferFromAX2009
        where nDXMappingDataTransferFromAX2009.FieldTyp == _fieldTyp
        && nDXMappingDataTransferFromAX2009.FromStringValue == _fromStringValue;

    return nDXMappingDataTransferFromAX2009;
}

/// <summary>
/// PaffH 20.08.22
/// </summary>
/// <param name = "_fieldTyp">NDXMappingDataFromAX2009FieldTyp</param>
/// <param name = "_fromStringValue">NDXFromStringValue</param>
/// <param name = "_useDialog">boolean</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXMappingDataTransferFromAX2009StringTyp</returns>
public static NDXMappingDataTransferFromAX2009StringTyp findOrCreate(
    NDXMappingDataFromAX2009FieldTyp _fieldTyp, 
    NDXFromStringValue _fromStringValue, 
    boolean _useDialog = true,
    boolean _doInsert = true)
{
    NDXMappingDataTransferFromAX2009StringTyp nDXMappingDataTransferFromAX2009;
    nDXMappingDataTransferFromAX2009 = NDXMappingDataTransferFromAX2009StringTyp::find(_fieldTyp, _fromStringValue, true);
    if (!nDXMappingDataTransferFromAX2009)
    {
        nDXMappingDataTransferFromAX2009.FieldTyp = _fieldTyp;
        nDXMappingDataTransferFromAX2009.FromStringValue = _fromStringValue;
        if (_useDialog)
        {
            Dialog dialog = new Dialog("@NDX:NDXSetMappingValue");
            DialogField dialogFieldFieldType = dialog.addFieldValue(enumStr(NDXMappingDataFromAX2009FieldTyp), _fieldTyp);
            dialogFieldFieldType.allowEdit(false);
            DialogField dialogFieldFromStringValue = dialog.addFieldValue(extendedTypeStr(NDXFromStringValue), _fromStringValue);
            dialogFieldFromStringValue.allowEdit(false);
            DialogField dialogFieldToStringValue = dialog.addField(extendedTypeStr(NDXToStringValue));
            DialogField dialogFieldMappingNotExist = dialog.addField(enumStr(NoYes));
            dialog.run();
            if (dialog.closedOk())
            {
                NDXToStringValue toStringValue = dialogFieldToStringValue.value();
                nDXMappingDataTransferFromAX2009.ToStringValue = toStringValue;
                nDXMappingDataTransferFromAX2009.MappingNotExist = dialogFieldMappingNotExist.value();
                if (_doInsert)
                {
                    nDXMappingDataTransferFromAX2009.insert();
                }
            }
        }
        else
        {
            if (_doInsert)
            {
                nDXMappingDataTransferFromAX2009.insert();
            }
        }
    }

    return nDXMappingDataTransferFromAX2009;
}

